'use strict';const fs=require('fs'),assert=require('assert'),crypto=require('crypto'),E=require('./campaign_editor'),root=require('path').resolve(__dirname,'..'),r=fs.readFileSync(root+'/build/naruto_role_swap_v0.1.5_EXPERIMENTAL.gba'),fresh=()=>new E.Editor(r),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),checks=[];function test(n,f){f();checks.push(n);console.log('PASS',n);}const pack=JSON.parse(fs.readFileSync(root+'/asset_import/generated/凯_头像_素材包.json')).asset,sprite=JSON.parse(fs.readFileSync(root+'/asset_import/generated/凯_战斗人物_素材包.json')).asset;
test('no-edit output retains exact ROM bytes',()=>assert.deepEqual(fresh().build(),new Uint8Array(r)));
test('malformed image and palette imports fail without residue',()=>{const m=fresh();for(const bad of[{...pack,width:81},{...pack,palette:[0,32768]},{...pack,indices:[999]}])assert.throws(()=>m.transaction('bad',()=>m.setPortraitAsset(47,1,bad)));assert.deepEqual(m.build(),new Uint8Array(r));assert.throws(()=>m.transaction('bad palette',()=>m.addPalette('bad',[0,-1])));});
test('portrait undo clears cached previews',()=>{const m=fresh(),old=m.renderPortrait(47).pixels;m.transaction('p',()=>m.setPortraitAsset(47,1,pack));assert.notDeepEqual(m.renderPortrait(47).pixels,old);m.undo();assert.deepEqual(m.renderPortrait(47).pixels,old);});
test('quick sprite roundtrip matches every cell and preserves shared original assets',()=>{const m=fresh();m.setQuickSpriteAsset(47,sprite);const b=m.build(),a=new E.Editor(b),info=a.spriteInfo(47);assert.equal(info.frameCount,20);const rendered=a.renderSpriteSheet(47);for(let f=0;f<20;f++)for(let y=0;y<64;y++)for(let x=0;x<64;x++){const src=(Math.floor(f/5)*64+y)*320+f%5*64+x,dest=(Math.floor(f/5)*128+40+y)*640+f%5*128+32+x,idx=sprite.indices[src];assert.deepEqual(Array.from(rendered.pixels.slice(dest*4,dest*4+4)),idx?Array.from(Uint8ClampedArray.from(E.AssetImport.rgb(sprite.palette[idx]))):[0,0,0,0]);}assert.deepEqual(b.slice(0x596ccc+5*144,0x596ccc+6*144),new Uint8Array(r.slice(0x596ccc+5*144,0x596ccc+6*144)));});
test('native sprite template packs back without visual changes',()=>{const m=fresh(),sheet=m.renderSpriteSheet(12),a=E.AssetImport.quantize(sheet,15);m.setSpriteAsset(12,0,a);const b=new E.Editor(m.build());assert.deepEqual(b.renderSpriteSheet(12).pixels,a.pixels);});
test('template rejects painted pixels outside original frame shapes',()=>{const m=fresh(),a=E.AssetImport.quantize(m.renderSpriteSheet(12),15);a.indices[0]=1;assert.throws(()=>m.setSpriteAsset(12,0,a),/范围之外/);});
test('terrain imports clear upper image layer without affecting neighboring cells',()=>{const m=fresh(),s=m.battleIds().find(s=>m.mapData(s).layers[1]),base=m.renderMap(s),tile={width:32,height:16,palette:[0,31],indices:Array(512).fill(1)};m.setTileAsset(s,0,0,tile,7);const image=m.renderMap(s);for(let y=0;y<image.height;y++)for(let x=0;x<image.width;x++){const p=(y*image.width+x)*4;assert.deepEqual(Array.from(image.pixels.slice(p,p+4)),x<32&&y<16?[255,0,0,255]:Array.from(base.pixels.slice(p,p+4)));}m.setTerrain(s,0,0,0);assert.equal(m.mapData(s).terrain[0],0);const again=new E.Editor(m.build());assert.deepEqual(again.renderMap(s).pixels,image.pixels);});
test('profiles and all assets survive project reload',()=>{const m=fresh();m.setQuickSpriteAsset(47,sprite);m.setPortraitAsset(47,1,pack,true);m.setCharacterProfile(47,12);m.addPalette('example',[0,31]);const p=m.project(sha(r)),n=fresh();n.importProject(p,sha(r));assert.deepEqual(n.build(),m.build());});
fs.writeFileSync(root+'/asset_import/evidence/import_unit_tests.json',JSON.stringify({result:'pass',checks},null,2));
